#include "ZZbox1LL.hpp"

#include <FArray.hpp>
#include <cmath>
#include <complex>
#include <constants_mod.hpp>
#include <mxpart_mod.hpp>
#include <sprods_com_mod.hpp>

using namespace constants_mod;
using namespace mxpart_mod;
using namespace sprods_com_mod;

//-----Author: R.K. Ellis (September 2013)
//-----Box coefficient for LL coupling
//-----Box D0(p1,p34,p2,mt,mt,mt,mt)
//-----Opposite off-shellnesses: so called easy box
//-----Xpp and Xmp refer to the initial state gluon polarizations
static void ZZbox1LLcore(int j1, int j2, int j3, int j4, int j5, int j6,
                         FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb,
                         double mt,
                         FArray2D<std::complex<double>>& Xpp, FArray2D<std::complex<double>>& Xmp,
                         FArray4D<std::complex<double>>& Xrat) {

  double mtsq, s134, s234;
  int k1, k2, k3 = 0, k4 = 0, k5 = 0, k6 = 0;
  std::complex<double> app0, app2, app4, amp2, amp4;

  //--- statement functions
  auto zab2 = [&za, &zb](int i1, int i2, int i3, int i4) {
    return za(i1, i2) * zb(i2, i4) + za(i1, i3) * zb(i3, i4);
  };

  auto funcpp2 = [&](int i1, int i2, int i3, int i4, int i5, int i6) {
    return -half * (
        + za(i1, i3) * za(i2, i5) * za(i3, i4) * zb(i4, i2) * zb(i4, i3) * zb(i6, i1)
        + za(i1, i3) * za(i1, i5) * za(i2, i3) * zb(i2, i1) * zb(i4, i3) * zb(i6, i1)
        - za(i1, i2) * za(i3, i4) * za(i3, i5) * zb(i4, i2) * zb(i4, i3) * zb(i6, i1)
        - za(i1, i5) * za(i2, i3) * zab2(i5, i3, i4, i2) * zb(i4, i1) * zb(i6, i5)
        - 4.0 * std::pow(za(i1, i5) * za(i2, i3), 2) * zb(i2, i1) * zb(i4, i3) * zb(i6, i5)
          / za(i1, i2)
        - za(i1, i3) * za(i2, i5) * za(i3, i5) * zb(i2, i1) * zb(i4, i3) * zb(i6, i5)
        + za(i1, i2) * std::pow(za(i3, i5), 2) * zb(i2, i1) * zb(i4, i3) * zb(i6, i5))
        / (std::pow(za(i1, i2), 2) * s(i3, i4) * s(i5, i6));
  };

  auto funcmp2 = [&](int i1, int i2, int i3, int i4, int i5, int i6) {
    return half * (
        - za(i5, i6) * zab2(i1, i3, i4, i2) * zab2(i3, i2, i4, i1)
          * zb(i4, i1) * std::pow(zb(i6, i2), 2)
          / (zab2(i2, i3, i4, i1) * std::pow(zb(i2, i1), 2))
        + std::pow(za(i1, i5), 2) * za(i2, i3)
          * zab2(i1, i3, i4, i2) * zab2(i2, i1, i3, i4) * zb(i6, i5)
          / (std::pow(za(i1, i2), 2) * zab2(i2, i3, i4, i1)))
        / (s(i3, i4) * s(i5, i6));
  };

  //--- end statement function

  mtsq = std::pow(mt, 2);

  k1 = j1;
  k2 = j2;
  for (int h3 = 1; h3 <= 2; ++h3) {
    if (h3 == 1) {
      k3 = j3;
      k4 = j4;
    } else if (h3 == 2) {
      k3 = j4;
      k4 = j3;
    }
    for (int h5 = 1; h5 <= 2; ++h5) {
      if (h5 == 1) {
        k5 = j5;
        k6 = j6;
      } else if (h5 == 2) {
        k5 = j6;
        k6 = j5;
      }
      s134 = s(k1, k3) + s(k1, k4) + s(k3, k4);
      s234 = s(k2, k3) + s(k2, k4) + s(k3, k4);

      //----Helicity 1^+ 2^+
      app0 = half * (two * za(k3, k2) * za(k3, k1) * za(k2, k5) * za(k1, k5)
             + std::pow(za(k3, k5) * za(k1, k2), 2)) * (s134 * s234 - s(k3, k4) * s(k5, k6))
             / (std::pow(za(k1, k2), 4) * za(k3, k4) * za(k5, k6));
      app2 = funcpp2(k1, k2, k3, k4, k5, k6) + funcpp2(k2, k1, k3, k4, k5, k6);

      app4 = two / (s(k3, k4) * s(k5, k6) * std::pow(za(k1, k2), 2))
             * (zb(k4, k1) * zab2(k1, k3, k4, k2) * za(k2, k5)
              - zb(k4, k2) * zab2(k2, k3, k4, k1) * za(k1, k5))
             * (za(k1, k3) * zb(k6, k2) / zab2(k1, k3, k4, k2)
              - za(k2, k3) * zb(k6, k1) / zab2(k2, k3, k4, k1));

      Xpp(h3, h5) = app0 + mtsq * app2 + std::pow(mtsq, 2) * app4;  // @coverage-probe
      //--- contribution to rational part (coefficient of mt^4)
      Xrat(2, 2, h3, h5) = app4;

      //----Helicity 1^- 2^+
      amp2 = funcmp2(k1, k2, k3, k4, k5, k6) + funcmp2(k1, k2, k5, k6, k3, k4);

      amp4 = two / (s(j1, j2) * s(k3, k4) * s(k5, k6) * std::pow(zab2(k2, k3, k4, k1), 2))
             * (za(k2, k5) * zb(k1, k4) * zab2(k1, k3, k4, k2)
              - za(k1, k5) * zb(k2, k4) * zab2(k2, k3, k4, k1))
             * (za(k2, k3) * zb(k1, k6) * zab2(k1, k3, k4, k2)
              - za(k1, k3) * zb(k2, k6) * zab2(k2, k3, k4, k1));

      Xmp(h3, h5) = mtsq * amp2 + std::pow(mtsq, 2) * amp4;
      //--- contribution to rational part (coefficient of mt^4)
      Xrat(1, 2, h3, h5) = amp4;
    }
  }

  return;
}

//-----Author: R.K. Ellis (September 2013)
//-----Box coefficient for LL coupling
//-----Box D0(p1,p34,p2,mt,mt,mt,mt)
//-----Opposite off-shellnesses: so called easy box
//-----Xpp and Xmp refer to the initial state gluon polarizations
void ZZbox1LL(int j1, int j2, int j3, int j4, int j5, int j6,
              FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb,
              double mt,
              FArray2D<std::complex<double>>& Xpp, FArray2D<std::complex<double>>& Xmp,
              FArray2D<std::complex<double>>& Xpm, FArray2D<std::complex<double>>& Xmm,
              FArray4D<std::complex<double>>& Xrat) {

  ZZbox1LLcore(j1, j2, j3, j4, j5, j6, zb, za, mt, Xpp, Xmp, Xrat);
  for (int h3 = 1; h3 <= 2; ++h3) {
    for (int h5 = 1; h5 <= 2; ++h5) {
      Xpm(h3, h5) = Xmp(3 - h3, 3 - h5);
      Xmm(h3, h5) = Xpp(3 - h3, 3 - h5);
      Xrat(2, 1, h3, h5) = Xrat(1, 2, 3 - h3, 3 - h5);
      Xrat(1, 1, h3, h5) = Xrat(2, 2, 3 - h3, 3 - h5);
    }
  }

  ZZbox1LLcore(j1, j2, j3, j4, j5, j6, za, zb, mt, Xpp, Xmp, Xrat);

  //--- compare with obtaining remaining coefficients by c.c.

  return;
}

extern "C" {

  void ZZbox1LL_wrapper(int j1, int j2, int j3, int j4, int j5, int j6,
                        std::complex<double>* fza, std::complex<double>* fzb,
                        double mt,
                        std::complex<double>* fXpp, std::complex<double>* fXmp,
                        std::complex<double>* fXpm, std::complex<double>* fXmm,
                        std::complex<double>* fXrat) {

    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);
    FArray2D<std::complex<double>> Xpp(fXpp, 2, 2);
    FArray2D<std::complex<double>> Xmp(fXmp, 2, 2);
    FArray2D<std::complex<double>> Xpm(fXpm, 2, 2);
    FArray2D<std::complex<double>> Xmm(fXmm, 2, 2);
    FArray4D<std::complex<double>> Xrat(fXrat, 2, 2, 2);

    ZZbox1LL(j1, j2, j3, j4, j5, j6, za, zb, mt, Xpp, Xmp, Xpm, Xmm, Xrat);
  }

}
